151: // wait waits for the waitgroup for the specified max timeout.
152: // Returns true if waiting timed out.
153: func wait(wg *sync.WaitGroup, ctx context.Context) error {
154: 	c := make(chan struct{})
155: 	go func() {
156: 		defer close(c)
157: 		wg.Wait()
158: 	}()
159: 
160: 	select {
161: 	case <-c:
162: 		return nil
163: 
164: 	case <-ctx.Done():
165: 		return ctx.Err()
166: 	}
167: }
