336: func (a *Client) copyFromRemote(
337: 	ctx context.Context,
338: 	w io.Writer,
339: 	remotePath string,
340: 	passThru PassThru,
341: 	preserveFileTimes bool,
342: ) (*FileInfos, error) {
343: 	session, err := a.sshClient.NewSession()
344: 	if err != nil {
345: 		return nil, fmt.Errorf("Error creating ssh session in copy from remote: %v", err)
346: 	}
347: 	defer session.Close()
348: 
349: 	wg := sync.WaitGroup{}
350: 	errCh := make(chan error, 4)
351: 	var fileInfos *FileInfos
352: 
353: 	wg.Add(1)
354: 	go func() {
355: 		var err error
356: 
357: 		defer func() {
358: 			// NOTE: this might send an already sent error another time, but since we only receive one, this is fine. On the "happy-path" of this function, the error will be `nil` therefore completing the "err<-errCh" at the bottom of the function.
359: 			errCh <- err
360: 			// We must unblock the go routine first as we block on reading the channel later
361: 			wg.Done()
