371: 		in, err := session.StdinPipe()
372: 		if err != nil {
373: 			errCh <- err
374: 			return
375: 		}
376: 		defer in.Close()
377: 
378: 		if preserveFileTimes {
379: 			err = session.Start(fmt.Sprintf("%s -pf %q", a.RemoteBinary, remotePath))
380: 		} else {
381: 			err = session.Start(fmt.Sprintf("%s -f %q", a.RemoteBinary, remotePath))
382: 		}
383: 		if err != nil {
384: 			errCh <- err
