399: 
400: 		fileInfos = fileInfo
401: 
402: 		err = Ack(in)
403: 		if err != nil {
404: 			errCh <- err
405: 			return
406: 		}
407: 
408: 		if passThru != nil {
409: 			r = passThru(r, fileInfo.Size)
410: 		}
