  "description": "Final report produced by the pc-lib-analyzer agent. The languages/code_metrics/tests blocks come verbatim from the code-metrics script (deterministic); every other block is reasoned by the model via its skill.",
  "type": "object",
  "required": ["library", "function_summary", "languages", "code_metrics",
               "tests", "license", "dependencies", "native_api",
               "runtime_surface", "build_env", "harmony_adaptation", "meta"],
  "properties": {
    "library": {
      "type": "object",
      "required": ["name", "source_url"],
      "properties": {
        "name": {"type": "string"},
        "kind": {"type": "string",
          "description": "model: 被分析对象的性质。推荐取值（开放，可扩并记入 meta.observations）：library（被 API 调用的三方库）/ application（终端用户启动运行的应用，如桌面/CLI）/ framework / tool / cli / service / plugin / other。缺省/旧报告按 library 处理。决定 dim-9 鸿蒙口径：library→模型A/B（重编+链接/桥接），application→模型C（整包应用打包并启动）。"},
        "package_name": {"type": ["string", "null"],
          "description": "model: distribution/package name from the manifest (PyPI/npm/Maven artifact/crate name), may differ from the repo dir name. Used to link this library into other libraries' dependency trees. Null if none/uncertain."},
        "aliases": {"type": "array", "items": {"type": "string"},
          "description": "model: 该库的其它已知名称（旧名/别名/常见拼写/CMake find_package 名/Maven groupId:artifactId 等），用于被别的库的依赖按名匹配上。无则省略或 []。"},
        "import_names": {"type": "array", "items": {"type": "string"},
          "description": "model: 实际 import/引入时用的名字（如 PyPI Pillow → import PIL；包名≠导入名时尤其有用）。无则省略或 []。"},
        "source_url": {"type": ["string", "null"]},
        "monorepo": {"type": "boolean",
          "description": "model: 被分析对象是 monorepo 的一个子目录时为 true。此时 source_url 仍为仓库根 URL，具体子目录见 source_subpath。缺省 false（整仓）。"},
        "source_subpath": {"type": ["string", "null"],
          "description": "model: monorepo 子目录分析时，被分析子目录相对仓库根的路径（如 \"components/cronet\"）。整仓分析为 null/省略。"},
        "analyzed_at": {"type": "string", "description": "ISO-8601 UTC"},
        "commit": {"type": ["string", "null"]},
        "one_liner": {"type": "string", "description": "model: <=120 char tagline"},
        "ecosystem": {
          "type": "string",
          "enum": ["python", "java", "nodejs", "cpp", "rust", "go", "dotnet", "other"],
          "description": "库的核心语言生态，由模型根据 manifest 与主语言判断。取值：python / java / nodejs / cpp / rust / go / dotnet / other"
        },
        "bindings": {
          "type": "array",
          "items": {"type": "string", "enum": ["python", "java", "nodejs", "cpp", "rust", "go", "dotnet", "other"]},
          "description": "model: 该库在核心生态之外对外提供绑定/包装的语言生态（如 C++ 核心 + Python/Java/C# 绑定 → [python, java, dotnet]）。无则 []。用于多语言库的生态展示。"
        }
      }
    },

    "function_summary": {
      "type": "object",
      "description": "Dimension 1 — MODEL (skill: function-summary). All prose fields here (summary, category name/description, domain, target_users) and library.one_liner are written in Simplified Chinese (简体中文).",
      "required": ["summary", "categories"],
      "properties": {
        "summary": {"type": "string", "description": "2-4 sentences: what it does, for whom."},
